def prime_fib(n: int) -> int:
    """
    prime_fib returns the n-th number that is a Fibonacci number and it's also prime.
    """
    def is_prime(num):
        if num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    def generate_fibonacci():
        a, b = 0, 1
        while True:
            yield a
            a, b = b, a + b

    count = 0
    for fib in generate_fibonacci():
        if is_prime(fib):
            count += 1
            if count == n:
                return fib

