def count_up_to(n):
    if n <= 1:
        return []

    def is_prime(num):
        if num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    prime_numbers = []
    for num in range(2, n):
        if is_prime(num):
            prime_numbers.append(num)
            if len(prime_numbers) == n:
                break

    return prime_numbers
```

