from heapq import *

class Solution:
    def minPath(self, grid, k):
        n = len(grid)
        pq = []
        for i in range(n):
            for j in range(n):
                if grid[i][j] <= k:
                    pq.append((grid[i][j], i, j))
        heapq.heapify(pq)
        while k > 0:
            val, i, j = heapq.heappop(pq)
            k -= 1
            for ni, nj in [(i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)]:
                if 0 <= ni < n and 0 <= nj < n:
                    heapq.heappush(pq, (grid[ni][nj], ni, nj))
        return list(pq)[0][0]
